CREATE TABLE test_reports (id UUID PRIMARY KEY,pipeline_run_id UUID NOT NULL REFERENCES pipeline_runs(id) ON DELETE CASCADE,pipeline_job_id UUID,source_name VARCHAR(512) NOT NULL,framework_hint VARCHAR(128),content_sha256 CHAR(64) NOT NULL,total_tests INTEGER NOT NULL,passed INTEGER NOT NULL,failed INTEGER NOT NULL,errors INTEGER NOT NULL,skipped INTEGER NOT NULL,duration_ms BIGINT,ingested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_test_report_source UNIQUE(pipeline_run_id,source_name,content_sha256));
CREATE TABLE test_suites (id UUID PRIMARY KEY,test_report_id UUID NOT NULL REFERENCES test_reports(id) ON DELETE CASCADE,name VARCHAR(512) NOT NULL,package_name VARCHAR(512),hostname VARCHAR(255),duration_ms BIGINT,suite_timestamp TIMESTAMPTZ);
CREATE TABLE test_case_executions (id UUID PRIMARY KEY,test_suite_id UUID NOT NULL REFERENCES test_suites(id) ON DELETE CASCADE,pipeline_run_id UUID NOT NULL REFERENCES pipeline_runs(id),stable_test_id CHAR(64) NOT NULL,test_id_algorithm VARCHAR(32) NOT NULL,class_name VARCHAR(512),test_name VARCHAR(512) NOT NULL,status VARCHAR(32) NOT NULL,duration_ms BIGINT,failure_kind VARCHAR(32),failure_type VARCHAR(255),failure_message TEXT,normalized_failure_message TEXT,failure_fingerprint VARCHAR(64),correlated_failure_event_id UUID,correlation_strength VARCHAR(16),stdout TEXT,stderr TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_test_cases_run ON test_case_executions(pipeline_run_id); CREATE INDEX idx_test_cases_stable ON test_case_executions(stable_test_id);
